export function getReviewedPrescriptionInputs(exerciseId) {
  return typeof exerciseId === "string" && Object.hasOwn(REVIEWED_PRESCRIPTION_INPUTS, exerciseId)
    ? REVIEWED_PRESCRIPTION_INPUTS[exerciseId] : null;
}
